'use client'
import { cn, Slot } from '@cascivo/core'
import type { HTMLAttributes, ReactNode } from 'react'
import styles from './contained-list.module.css'

export interface ContainedListProps extends HTMLAttributes<HTMLDivElement> {
  label: ReactNode
  kind?: 'on-page' | 'disclosed'
  action?: ReactNode
}

export function ContainedList({
  label,
  kind = 'on-page',
  action,
  className,
  children,
  ...props
}: ContainedListProps) {
  return (
    <div
      data-kind={kind}
      className={cn(styles['root'], className as string | undefined)}
      {...props}
    >
      <div className={styles['header']}>
        <h3 className={styles['label']}>{label}</h3>
        {action ? <div className={styles['action']}>{action}</div> : null}
      </div>
      <ul className={styles['list']}>{children}</ul>
    </div>
  )
}

export interface ContainedListItemProps extends HTMLAttributes<HTMLDivElement> {
  asChild?: boolean
}

export function ContainedListItem({
  asChild = false,
  onClick,
  className,
  children,
  ...props
}: ContainedListItemProps) {
  const interactive = asChild || typeof onClick === 'function'
  const Comp = asChild ? Slot : 'div'
  return (
    <li className={styles['item']} data-interactive={interactive ? '' : undefined}>
      <Comp
        className={cn(styles['itemContent'], className as string | undefined)}
        onClick={onClick}
        {...(props as Record<string, unknown>)}
      >
        {children}
      </Comp>
    </li>
  )
}

@layer cascivo.component {
  .root {
    font-family: var(--cascivo-font-sans);
    color: var(--cascivo-color-text);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-surface);
    overflow: hidden;
    background-color: var(--cascivo-color-surface);
  }

  .header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--cascivo-space-3);
    padding-inline: var(--cascivo-space-4);
    padding-block: var(--cascivo-space-3);
  }

  .root[data-kind='disclosed'] .header {
    background-color: var(--cascivo-color-bg-subtle);
    border-block-end: 1px solid var(--cascivo-color-border);
  }

  .label {
    margin: 0;
    font-size: var(--cascivo-text-sm);
    font-weight: var(--cascivo-font-semibold);
    line-height: var(--cascivo-leading-tight);
    color: var(--cascivo-color-text);
  }

  .action {
    display: inline-flex;
    align-items: center;
    gap: var(--cascivo-space-2);
  }

  .list {
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .item {
    border-block-start: 1px solid var(--cascivo-color-border);
  }

  .list > .item:first-child {
    border-block-start: none;
  }

  .root[data-kind='disclosed'] .list > .item:first-child {
    border-block-start: none;
  }

  .itemContent {
    display: flex;
    align-items: center;
    gap: var(--cascivo-space-3);
    inline-size: 100%;
    box-sizing: border-box;
    padding-inline: var(--cascivo-space-4);
    padding-block: var(--cascivo-space-3);
    font: inherit;
    color: inherit;
    text-align: start;
    text-decoration: none;
  }

  .item[data-interactive] .itemContent {
    cursor: pointer;
    background-color: transparent;
    border: none;
    transition: background-color var(--cascivo-duration-150) var(--cascivo-ease-out);
  }

  .item[data-interactive] .itemContent:hover {
    background-color: var(--cascivo-color-bg-subtle);
  }

  .item[data-interactive] .itemContent:focus-visible {
    outline: none;
    box-shadow: var(--cascivo-focus-ring);
  }
}

@media (forced-colors: active) {
  .root {
    border: 1px solid CanvasText;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'ContainedList',
  description: 'Labelled list of rows inside a bordered container',
  category: 'display',
  // A static bordered list — the rows are all in the server HTML.
  clientJs: 'enhancement',
  states: [],
  variants: ['on-page', 'disclosed'],
  sizes: [],
  props: [
    {
      name: 'label',
      nameVisibility: 'visible',
      description: 'Text label for the control.',
      type: 'ReactNode',
      required: true,
    },
    {
      name: 'kind',
      description: "Visual treatment — 'on-page' or 'disclosed'.",
      type: "'on-page' | 'disclosed'",
      required: false,
      default: 'on-page',
    },
    {
      name: 'action',
      description: 'Primary action shown in the component.',
      type: 'ReactNode',
      required: false,
    },
  ],
  tokens: [
    '--cascivo-color-surface',
    '--cascivo-color-border',
    '--cascivo-color-bg-subtle',
    '--cascivo-radius-surface',
    '--cascivo-focus-ring',
  ],
  accessibility: { role: 'list', wcag: '2.2-AA', keyboard: ['Tab', 'Enter', 'Space'] },
  examples: [
    {
      title: 'Basic contained list',
      code: `<ContainedList label="Members">\n  <ContainedListItem>Ada Lovelace</ContainedListItem>\n  <ContainedListItem>Alan Turing</ContainedListItem>\n</ContainedList>`,
    },
    {
      title: 'Interactive rows',
      code: `<ContainedList label="Settings" kind="disclosed">\n  <ContainedListItem asChild>\n    <button type="button" onClick={open}>Profile</button>\n  </ContainedListItem>\n</ContainedList>`,
    },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['list', 'container', 'rows', 'group'],
  intent: {
    whenToUse: [
      'Grouping a short set of related rows under a visible heading in a bordered surface',
      'Presenting selectable or navigable rows (settings groups, member lists)',
      'Separating a labelled cluster of items from surrounding page content',
    ],
    whenNotToUse: [
      'A long, virtualised data set — use a Table or DataList instead',
      'Plain bulleted prose where the container border adds no meaning — use List',
    ],
    antiPatterns: [
      {
        bad: 'Putting interactive controls on a plain ContainedListItem div',
        good: 'Use ContainedListItem asChild with a <button> or <a> so the row is keyboard-focusable',
        why: 'A non-interactive div gives no focus or role semantics to assistive tech',
      },
    ],
    related: [
      {
        name: 'List',
        relationship: 'alternative',
        reason: 'List is for unbordered prose lists; ContainedList adds a labelled surface',
      },
      {
        name: 'ContainedListItem',
        relationship: 'contains',
        reason: 'Each row is a ContainedListItem',
      },
    ],
    a11yRationale:
      'The container heading labels the ul/li structure; interactive rows must slot a real button or link via asChild so role and focus are native, not faked on a div',
    flexibility: [
      {
        area: 'kind',
        level: 'flexible',
        note: 'on-page sits inline; disclosed adds a header band for menus and popovers',
      },
      {
        area: 'list semantics',
        level: 'strict',
        note: 'Rows are always ul/li; do not replace with generic divs',
      },
    ],
  },
}
